                    marks[c].append((v,min(rs)))
    out=[row[:] for row in O]
    for c,mk in marks.items():
        mk.sort()
        covered=-1
        for v,r in mk:
            if r<=covered: continue
            for rr in range(max(covered+1,r),H):
                out[rr][c]=v
                covered=rr
